#include <bits/stdc++.h>
using namespace std;

using ll = long long;
ll inverse_mod(ll a, ll m) {
	assert(m > 0);
	if (m == 1) return 0;
	a %= m;
	if (a < 0) a += m;
	assert(a != 0);
	if (a == 1) return 1;
	return m - inverse_mod(m, a) * m / a;
}

template <int MOD_> struct Modular {
private:
	int val;
public:
	static const int MOD = MOD_;

	Modular() : val(0) {}
	Modular(ll v_) : val(int(v_ % MOD)) { if (val < 0) val += MOD; }
	explicit operator int () const { return val; }
	friend bool operator == (const Modular& a, const Modular& b) { return a.val == b.val; }
	friend bool operator != (const Modular& a, const Modular& b) { return a.val != b.val; }

	Modular operator ~ () const {
		Modular res;
		res.val = inverse_mod(val, MOD);
		return res;
	}

	Modular& operator += (const Modular& o) {
		val += o.val;
		if (val >= MOD) val -= MOD;
		return *this;
	}
	Modular& operator -= (const Modular& o) {
		val -= o.val;
		if (val < 0) val += MOD;
		return *this;
	}
	Modular& operator *= (const Modular& o) {
		val = int(ll(val) * ll(o.val) % MOD);
		return *this;
	}
	Modular& operator /= (const Modular& o) {
		return *this *= (~o);
	}

	friend Modular operator + (const Modular& a, const Modular& b) { return Modular(a) += b; }
	friend Modular operator - (const Modular& a, const Modular& b) { return Modular(a) -= b; }
	friend Modular operator * (const Modular& a, const Modular& b) { return Modular(a) *= b; }
	friend Modular operator / (const Modular& a, const Modular& b) { return Modular(a) /= b; }
};

