import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static long inverse_mod(long a, long m) {
        if (m == 1) return 0;
        a %= m;
        if (a < 0) a += m;
        if (a == 0) throw new ArithmeticException("Inverse does not exist");
        if (a == 1) return 1;
        return m - inverse_mod(m, a) * m / a;
    }

    static class Modular {
        int val;

        public Modular() {
            this.val = 0;
        }

        public Modular(long v) {
            this.val = (int)(v % MOD);
            if (this.val < 0) this.val += MOD;
        }

        public static Modular add(Modular a, Modular b) {
            Modular res = new Modular();
            res.val = a.val + b.val;
            if (res.val >= MOD) res.val -= MOD;
            return res;
        }

        public static Modular subtract(Modular a, Modular b) {
            Modular res = new Modular();
            res.val = a.val - b.val;
            if (res.val < 0) res.val += MOD;
            return res;
        }

        public static Modular multiply(Modular a, Modular b) {
            return new Modular(((long)a.val * b.val) % MOD);
        }

        public static Modular divide(Modular a, Modular b) {
            return a.multiply(b.inverse());
        }

        public Modular inverse() {
            return new Modular(inverse_mod(this.val, MOD));
        }

        public String toString() {
            return Integer.toString(val);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        final int n = 6;
        Modular[][] p = new Modular[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                p[i][j] = new Modular(0);
            }
        }

        int _n = Integer.parseInt(br.readLine());
        for (int i = 0; i < _n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < _n; j++) {
                int a = Integer.parseInt(st.nextToken());
                p[i][j] = new Modular(a).divide(new Modular(100));
            }
        }

        final int f = 20;
        Modular[][] sets = new Modular[2][1 << f];
        for (int t = 0; t < 2; t++) {
            for (int j = 0; j < (1 << f); j++) {
                sets[t][j] = new Modular(0);
            }
        }

        List<Integer>[] masks = new List[2];
        masks[0] = new ArrayList<>();
        masks[1] = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                for (int k = 0; k < j; k++) {
                    int mask0 = (1 << i) ^ (1 << j) ^ (1 << k);
                    masks[0].add(mask0);
                    int mask1 = ((1 << n) - 1) ^ mask0;
                    masks[1].add(mask1);
                }
            }
        }

        if (f != masks[0].size()) {
            throw new RuntimeException("Mismatch in mask size");
        }

        for (int t = 0; t < 2; t++) {
            int totalMasks = masks[t].size();
            for (int e = 0; e < (1 << (n / 2 * n)); e++) {
                Modular prob = new Modular(1);
                int[] edges = new int[n / 2];
                Arrays.fill(edges, 0);
                for (int i = 0; i < n / 2 * n; i++) {
                    boolean r = ((e >> i) & 1) == 1;
                    Modular pp = p[(i / n) * 2 + t][i % n];
                    prob = r ? Modular.multiply(prob, pp) : Modular.multiply(prob, new Modular(1).subtract(pp));
                    edges[i / n] |= (r ? 1 : 0) << (i % n);
                }
                int work_mask = 0;
                for (int a = 0; a < totalMasks; a++) {
                    int mask = masks[t].get(a);
                    int[] r = new int[n / 2];
                    for (int i = 0; i < n / 2; i++) {
                        r[i] = edges[i] & mask;
                    }
                    if (r[0] != 0 && r[1] != 0 && r[2] != 0) {
                        int unionCount = 0;
                        int combined = r[0] | r[1] | r[2];
                        if (Integer.bitCount(combined) == 3) {
                            int x = Integer.bitCount(r[0] | r[1]);
                            int y = Integer.bitCount(r[0] | r[2]);
                            int z = Integer.bitCount(r[1] | r[2]);
                            if (x >= 2 && y >= 2 && z >= 2) {
                                work_mask |= (1 << a);
                            }
                        }
                    }
                }
                sets[t][work_mask] = Modular.add(sets[t][work_mask], prob);
            }
        }

        for (int i = 0; i < f; i++) {
            for (int j = 0; j < (1 << f); j++) {
                if (((j >> i) & 1) == 1) continue;
                sets[0][j ^ (1 << i)] = Modular.add(sets[0][j ^ (1 << i)], sets[0][j]);
            }
        }

        Modular answer = new Modular(0);
        for (int j = 0; j < (1 << f); j++) {
            Modular temp = Modular.multiply(sets[0][j], sets[1][((1 << f) - 1) ^ j]);
            answer = Modular.add(answer, temp);
        }

        answer = new Modular(1).subtract(answer);
        System.out.println(answer);
    }
}
